/* tparse: release-name and file-list parser (C11, libc only).
 *
 * Stage 1a scope: extension-bucket counting, total_size sanity,
 * category hints, and a stub-safe tp_feature_text (name tokens +
 * count/category feature tokens). TV/season/episode/resolution and
 * name flags land in later stages.
 */
#include "tparse_internal.h"
#include "adult_terms.h" /* generated by `cm gen-header` from config/adult_terms.json */

#include <ctype.h>
#include <stdio.h>
#include <string.h>

/* Extension buckets. Matched case-insensitively against the trailing
 * extension after the last '.' of the basename of the file path.
 * cbz/cbr count as archives (and drive the comic hint). */
static const char *const k_video_exts[] = {
    "mkv", "mp4", "avi", "mpg", "mpeg", "wmv", "mov", "flv", "webm", "m4v",
    "ts",  "vob", "iso", NULL
};
static const char *const k_audio_exts[] = {
    "mp3", "flac", "wav", "ape", "m4a", "wma", "ogg", "opus", "aac", NULL
};
static const char *const k_image_exts[] = {
    "jpg", "jpeg", "png", "webp", "gif", "bmp", "tiff", NULL
};
static const char *const k_archive_exts[] = {
    "zip", "rar", "7z", "tar", "gz", "bz2", "cbz", "cbr", NULL
};
static const char *const k_exec_exts[] = {
    "exe", "msi", "apk", "bin", NULL
};
static const char *const k_doc_exts[] = {
    "pdf", "epub", "mobi", "txt", "nfo", NULL
};

static int ext_in(const char *ext, const char *const *list) {
    for (size_t i = 0; list[i] != NULL; i++) {
        if (strcmp(ext, list[i]) == 0) return 1;
    }
    return 0;
}

/* Extract the trailing extension of `path` (after the last '.' of the
 * basename) into `out`, lowercased. Dotfiles (a leading dot with nothing
 * before it in the basename) and missing/empty extensions return 0. */
static int file_ext(const char *path, char *out, size_t cap) {
    const char *base = strrchr(path, '/');
    base = (base != NULL) ? base + 1 : path;
    const char *dot = strrchr(base, '.');
    if (dot == NULL || dot == base) return 0;
    const char *ext = dot + 1;
    size_t len = strlen(ext);
    if (len == 0 || len + 1 > cap) return 0;
    for (size_t i = 0; i < len; i++) {
        out[i] = (char)tolower((unsigned char)ext[i]);
    }
    out[len] = '\0';
    return 1;
}

/* --- Stage 1c: file-list (season, episode) pair evidence ---------------- */

/* Cap: pairs beyond this are silently dropped (bounded memory for adversarial
 * file lists; the tv_kind decision is unaffected). */
#define TP_MAX_PAIRS 256
/* Mirrors SE_MAX_EPS in name.c: a longer cluster contributes endpoints only. */
#define TP_CLUSTER_MAX_EPS 32

typedef struct {
    int season, ep;
} tp_pair_t;

typedef struct {
    tp_pair_t pairs[TP_MAX_PAIRS];
    int n_pairs;                 /* pairs across files + name */
    int n_file_pairs;            /* pairs from the file list only */
    int n_seasons;               /* distinct season values */
    int n_eps;                   /* distinct episode values */
    int season_lo, season_hi, episode_lo, episode_hi;
    int n_files_with_pairs;      /* video files that contributed a pair */
    int daily;                   /* a dated video basename with no pairs */
    int incomplete;              /* a hole inside a season's episode run */
    int season_gap;              /* a whole season missing inside lo..hi */
    int file_res;                /* most common resolution in video basenames */
} tp_file_ev_t;

static const int k_res_vals[4] = { 480, 720, 1080, 2160 };

static int res_slot(int res) {
    for (int i = 0; i < 4; i++) {
        if (k_res_vals[i] == res) return i;
    }
    return -1;
}

/* Insert a (season, episode) pair, deduped; a file origin wins on collision. */
static void ev_add_pair(tp_file_ev_t *ev, int season, int ep) {
    if (ep <= 0 || season < 0) return;
    for (int i = 0; i < ev->n_pairs; i++) {
        if (ev->pairs[i].season == season && ev->pairs[i].ep == ep) return;
    }
    if (ev->n_pairs >= TP_MAX_PAIRS) return;
    ev->pairs[ev->n_pairs].season = season;
    ev->pairs[ev->n_pairs].ep = ep;
    ev->n_pairs++;
}

/* Add a whole [lo..hi] cluster (min/max normalised first; a cluster longer
 * than TP_CLUSTER_MAX_EPS contributes its two endpoints only). */
static void ev_add_cluster(tp_file_ev_t *ev, int season, int lo, int hi) {
    int a = lo;
    int b = (hi > lo) ? hi : lo;
    if (a <= 0) return;
    if (b - a + 1 > TP_CLUSTER_MAX_EPS) {
        ev_add_pair(ev, season, a);
        ev_add_pair(ev, season, b);
        return;
    }
    for (int e = a; e <= b; e++) ev_add_pair(ev, season, e);
}

static int ev_has_season(const tp_file_ev_t *ev, int season) {
    for (int i = 0; i < ev->n_pairs; i++) {
        if (ev->pairs[i].season == season) return 1;
    }
    return 0;
}

/* Incomplete: a season whose known episodes have >= 2 entries but leave a
 * hole in the lo..hi run. Computed from file pairs only (the name keeps a
 * single lo/hi pair, so it cannot witness a hole). */
static void ev_check_holes(tp_file_ev_t *ev) {
    for (int i = 0; i < ev->n_pairs; i++) {
        int s = ev->pairs[i].season;
        int lo = 0, hi = 0, cnt = 0;
        int first = 1;
        for (int j = 0; j < ev->n_pairs; j++) {
            if (ev->pairs[j].season != s) continue;
            if (first || ev->pairs[j].ep < lo) lo = ev->pairs[j].ep;
            if (first || ev->pairs[j].ep > hi) hi = ev->pairs[j].ep;
            first = 0;
            cnt++;
        }
        if (cnt >= 2 && hi - lo + 1 > cnt) {
            ev->incomplete = 1;
            return;
        }
    }
}

static void ev_finish(tp_file_ev_t *ev) {
    if (ev->n_pairs == 0) return;
    ev->season_lo = ev->season_hi = ev->pairs[0].season;
    ev->episode_lo = ev->episode_hi = ev->pairs[0].ep;
    for (int i = 0; i < ev->n_pairs; i++) {
        if (ev->pairs[i].season < ev->season_lo) ev->season_lo = ev->pairs[i].season;
        if (ev->pairs[i].season > ev->season_hi) ev->season_hi = ev->pairs[i].season;
        if (ev->pairs[i].ep < ev->episode_lo) ev->episode_lo = ev->pairs[i].ep;
        if (ev->pairs[i].ep > ev->episode_hi) ev->episode_hi = ev->pairs[i].ep;
    }
    for (int i = 0; i < ev->n_pairs; i++) {
        int seen = 0;
        for (int j = 0; j < i; j++) {
            if (ev->pairs[j].season == ev->pairs[i].season) { seen = 1; break; }
        }
        if (!seen) ev->n_seasons++;
        seen = 0;
        for (int j = 0; j < i; j++) {
            if (ev->pairs[j].ep == ev->pairs[i].ep) { seen = 1; break; }
        }
        if (!seen) ev->n_eps++;
    }
    for (int s = ev->season_lo; s <= ev->season_hi; s++) {
        if (!ev_has_season(ev, s)) { ev->season_gap = 1; break; }
    }
}

/* Resolution winner: most common among video basenames; the name resolution
 * breaks ties, then the smaller value keeps the choice deterministic. */
static int ev_pick_res(const int votes[4], int name_res) {
    int best = 0;
    for (int i = 0; i < 4; i++) {
        if (votes[i] > best) best = votes[i];
    }
    if (best == 0) return 0;
    int chosen = 0;
    for (int i = 0; i < 4; i++) {
        if (votes[i] == best) { chosen = k_res_vals[i]; break; }
    }
    if (name_res != 0) {
        for (int i = 0; i < 4; i++) {
            if (votes[i] == best && k_res_vals[i] == name_res) return name_res;
        }
    }
    return chosen;
}

/* Collect (season, episode) evidence from the video files and the name.
 * Excluded files (samples/extras, see name.c) never contribute pairs. */
static void collect_file_ev(const tp_file_t *files, int n_files,
                            const tp_name_info_t *info, tp_file_ev_t *ev) {
    memset(ev, 0, sizeof(*ev));
    int votes[4] = { 0, 0, 0, 0 };

    for (int i = 0; i < n_files; i++) {
        if (files[i].path == NULL) continue;
        char ext[16];
        if (!file_ext(files[i].path, ext, sizeof ext)) continue;
        if (!ext_in(ext, k_video_exts)) continue;

        tp_name_info_t fi;
        tp_path_scan(files[i].path, &fi);
        int slot = res_slot(fi.resolution);
        if (slot >= 0) votes[slot]++;

        if (tp_path_is_excluded(files[i].path)) continue;
        int before = ev->n_pairs;
        ev_add_cluster(ev, fi.season_lo, fi.episode_lo, fi.episode_hi);
        if (ev->n_pairs > before) ev->n_files_with_pairs++;
        else if (fi.tv_kind == TP_TV_DAILY) ev->daily = 1;
    }
    ev->n_file_pairs = ev->n_pairs;
    ev_check_holes(ev);

    /* The name contributes its own cluster, but never against file evidence:
     * a name season the files do not show is dropped (file evidence wins). */
    if (info != NULL && info->episode_lo > 0 &&
        (ev->n_pairs == 0 || ev_has_season(ev, info->season_lo))) {
        ev_add_cluster(ev, info->season_lo, info->episode_lo, info->episode_hi);
    }

    ev_finish(ev);
    ev->file_res = ev_pick_res(votes, (info != NULL) ? info->resolution : 0);
}

/* tv_kind from the pair set. `out` already carries the name fields/flags. */
static void apply_file_ev(const tp_file_ev_t *ev, const tp_name_info_t *info, tp_result_t *out) {
    if (ev->n_pairs == 0) {
        out->tv_kind = ev->daily ? TP_TV_DAILY : info->tv_kind;
        return;
    }
    out->season_lo = ev->season_lo;
    out->season_hi = ev->season_hi;
    out->episode_lo = ev->episode_lo;
    out->episode_hi = ev->episode_hi;
    if (ev->incomplete) out->flags |= TP_F_INCOMPLETE;
    if (ev->n_pairs == 1) {
        out->tv_kind = TP_TV_EPISODE;
    } else if (ev->n_seasons == 1) {
        /* One season, many episodes: a single video file's cluster is a
         * multi-episode release, several files are a season pack. */
        out->tv_kind = (ev->n_files_with_pairs <= 1) ? TP_TV_MULTI_EPISODE
                                                     : TP_TV_SEASON_PACK;
    } else if (((out->flags & TP_F_COMPLETE) != 0 ||
                info->season_lo != info->season_hi) && /* name-level S01-S05 */
               !ev->season_gap) {
        /* Several seasons with no gaps: a complete series whenever the name
         * says so, either with the explicit "Complete" token or with a
         * name-level season range (classifier.md §4). */
        out->tv_kind = TP_TV_COMPLETE_SERIES;
    } else {
        out->tv_kind = TP_TV_MULTI_SEASON;
    }
}

int tp_parse(const char *name, const tp_file_t *files, int n_files, int64_t total_size, tp_result_t *out) {
    if (name == NULL || out == NULL) return TP_EINVAL;
    if (n_files < 0) n_files = 0;
    if (files == NULL) n_files = 0; /* a NULL list is "no files" */

    memset(out, 0, sizeof(*out));

    int has_cbz_cbr = 0;
    if (files != NULL && n_files > 0) {
        for (int i = 0; i < n_files; i++) {
            if (files[i].path == NULL) continue;
            char ext[16];
            if (!file_ext(files[i].path, ext, sizeof ext)) continue;
            if (ext_in(ext, k_video_exts)) {
                out->n_video++;
            } else if (ext_in(ext, k_audio_exts)) {
                out->n_audio++;
            } else if (ext_in(ext, k_image_exts)) {
                out->n_image++;
            } else if (ext_in(ext, k_archive_exts)) {
                out->n_archive++;
                if (strcmp(ext, "cbz") == 0 || strcmp(ext, "cbr") == 0) has_cbz_cbr = 1;
            } else if (ext_in(ext, k_exec_exts)) {
                out->n_exec++;
            } else if (ext_in(ext, k_doc_exts)) {
                out->n_doc++;
            }
        }
    }

    /* total_size sanity: 0 with files present means "sum the files".
     * Consumed by later stages (resolution heuristics); kept exact now.
     * Saturating: adversarial sizes must not overflow (UB). */
    int64_t effective_size = total_size;
    if (effective_size == 0 && files != NULL && n_files > 0) {
        effective_size = 0;
        for (int i = 0; i < n_files; i++) {
            if (files[i].size > 0 && effective_size > INT64_MAX - files[i].size) {
                effective_size = INT64_MAX;
                break;
            }
            if (files[i].size < 0 && effective_size < INT64_MIN - files[i].size) {
                effective_size = INT64_MIN;
                break;
            }
            effective_size += files[i].size;
        }
    }
    (void)effective_size;

    /* category hints: deterministic, first hit wins. */
    int hint = TP_CAT_UNKNOWN;
    if (has_cbz_cbr && out->n_archive > 0) {
        hint = TP_CAT_COMIC;
    } else if (out->n_audio > 0 && out->n_video == 0) {
        hint = TP_CAT_MUSIC;
    } else if (out->n_doc > 0 && out->n_video == 0 && out->n_audio == 0) {
        hint = TP_CAT_EBOOK;
    } else if (out->n_exec > 0) {
        hint = TP_CAT_SOFTWARE;
    } else if (out->n_image > 0 && out->n_video == 0 && out->n_audio == 0) {
        hint = TP_CAT_IMAGE;
    }
    out->category_hint = hint;

    /* name-level parse (Stage 1b): season/episode/resolution/flags are always
     * recorded from the name; the anime hint only applies when the file-list
     * hints are unknown. tv_kind (Stage 1c) is decided from the file-list
     * (season, episode) pair set when there is one, and from the name alone
     * otherwise. */
    tp_name_info_t info;
    tp_name_scan(name, &info);
    out->season_lo = info.season_lo;
    out->season_hi = info.season_hi;
    out->episode_lo = info.episode_lo;
    out->episode_hi = info.episode_hi;
    out->resolution = info.resolution;
    out->flags |= info.flags;
    if (info.cat_hint != TP_CAT_UNKNOWN && out->category_hint == TP_CAT_UNKNOWN) {
        out->category_hint = info.cat_hint;
    }
    if (n_files > 0) {
        tp_file_ev_t ev;
        collect_file_ev(files, n_files, &info, &ev);
        apply_file_ev(&ev, &info, out);
    } else {
        out->tv_kind = info.tv_kind;
    }
    return TP_OK;
}

/* --- tp_feature_text --------------------------------------------------- */

typedef struct {
    char *buf;    /* NULL: measure only */
    size_t cap;
    size_t len;    /* chars written so far */
    size_t needed; /* total chars that would be written */
} writer_t;

static void w_char(writer_t *w, char c) {
    w->needed++;
    if (w->buf != NULL && w->len + 1 < w->cap) w->buf[w->len++] = c;
}

static void w_put(writer_t *w, const char *s, size_t n) {
    for (size_t i = 0; i < n; i++) w_char(w, s[i]);
}

/* Normalised name tokens: split on non-alphanumeric, lowercase, skip empties. */
static void put_name_tokens(writer_t *w, const char *name) {
    size_t i = 0;
    size_t n = strlen(name);
    while (i < n) {
        while (i < n && !isalnum((unsigned char)name[i])) i++;
        size_t j = i;
        while (j < n && isalnum((unsigned char)name[j])) j++;
        if (j > i) {
            if (w->needed > 0) w_char(w, ' ');
            for (size_t k = i; k < j; k++) {
                w_char(w, (char)tolower((unsigned char)name[k]));
            }
        }
        i = j;
    }
}

static const char *cat_name(int c) {
    switch (c) {
        case TP_CAT_MOVIE: return "movie";
        case TP_CAT_TV: return "tv";
        case TP_CAT_ANIME: return "anime";
        case TP_CAT_MUSIC: return "music";
        case TP_CAT_AUDIOBOOK: return "audiobook";
        case TP_CAT_EBOOK: return "ebook";
        case TP_CAT_COMIC: return "comic";
        case TP_CAT_SOFTWARE: return "software";
        case TP_CAT_GAME: return "game";
        case TP_CAT_IMAGE: return "image";
        case TP_CAT_OTHER: return "other";
        default: return "unknown";
    }
}

static void put_int_token(writer_t *w, const char *prefix, int v) {
    char tok[64];
    int n = snprintf(tok, sizeof tok, "%s%d", prefix, v);
    if (n <= 0) return;
    if (w->needed > 0) w_char(w, ' ');
    w_put(w, tok, (size_t)n);
}

static void put_str_token(writer_t *w, const char *prefix, const char *s) {
    size_t pl = strlen(prefix);
    size_t sl = strlen(s);
    if (w->needed > 0) w_char(w, ' ');
    w_put(w, prefix, pl);
    w_put(w, s, sl);
}

static void put_feature_tokens(writer_t *w, const tp_result_t *r) {
    put_int_token(w, "__nvideo_", r->n_video);
    put_int_token(w, "__naudio_", r->n_audio);
    put_int_token(w, "__nimage_", r->n_image);
    put_int_token(w, "__narchive_", r->n_archive);
    put_int_token(w, "__nexec_", r->n_exec);
    put_int_token(w, "__ndoc_", r->n_doc);
    if (w->needed > 0) w_char(w, ' ');
    w_put(w, "__ncat_", 7);
    w_put(w, cat_name(r->category_hint), strlen(cat_name(r->category_hint)));
}

/* Stage 1b: `__src_<name>` (from the name; the struct has no source field)
 * and `__res_<480|720|1080|2160>` (from the result) after the existing
 * tokens. Neither is emitted when nothing was detected. */
static void put_source_res_tokens(writer_t *w, const char *name, const tp_name_info_t *info, const tp_result_t *r) {
    if (r == NULL || name == NULL || info == NULL) return;
    if (info->source != TP_SRC_NONE) put_str_token(w, "__src_", tp_source_name(info->source));
    if (r->resolution != 0) put_int_token(w, "__res_", r->resolution);
}

static const char *tv_name(int kind) {
    switch (kind) {
        case TP_TV_EPISODE: return "episode";
        case TP_TV_MULTI_EPISODE: return "multi_episode";
        case TP_TV_SEASON_PACK: return "season_pack";
        case TP_TV_MULTI_SEASON: return "multi_season";
        case TP_TV_COMPLETE_SERIES: return "complete_series";
        case TP_TV_DAILY: return "daily";
        default: return "none";
    }
}

/* Stage 1c appends only whole tokens: a truncated tail never leaves a
 * partial token behind (the Stage 1b part keeps byte truncation). */
static void w_token(writer_t *w, const char *prefix, const char *val) {
    size_t pl = strlen(prefix);
    size_t vl = strlen(val);
    size_t sep = (w->needed > 0) ? 1 : 0;
    size_t total = sep + pl + vl;
    if (w->buf != NULL && w->len + total < w->cap) {
        if (sep) w_char(w, ' ');
        w_put(w, prefix, pl);
        w_put(w, val, vl);
    } else {
        w->needed += total;
    }
}

static void w_int_token(writer_t *w, const char *prefix, int v) {
    char tok[64];
    int n = snprintf(tok, sizeof tok, "%s%d", prefix, v);
    if (n <= 0) return;
    w_token(w, "", tok);
}

/* Stage 1c: file-derived tokens, only ever appended when a file list is
 * present, so name-only output stays byte-identical to Stage 1b.
 * `__fres_` is a *video* resolution: file basenames first, the name as
 * tiebreak, nothing for a list without video files. */
static void put_file_tokens(writer_t *w, const tp_file_ev_t *ev, int n_files,
                            const tp_result_t *r, int name_res) {
    w_int_token(w, "__nfiles_", n_files);
    w_int_token(w, "__sep_", ev->n_seasons);
    w_int_token(w, "__ep_", ev->n_eps);
    int fres = (ev->file_res != 0) ? ev->file_res : ((r->n_video > 0) ? name_res : 0);
    if (fres != 0) w_int_token(w, "__fres_", fres);
    w_token(w, "__ftv_", tv_name(r->tv_kind));
}

/* Stage 3b-fix: file-extension evidence. The teacher saw real file lists;
 * the name tokens alone carry none of it, so the extension mix
 * (mkv/mp4 vs jpg/png vs exe/apk vs epub/pdf vs mp3/flac/cue) is appended as
 * bounded, deterministic, libc-only tokens:
 *  - only alnum extensions of 1..TP_MAX_EXT_LEN chars are eligible, so every
 *    token is one fastText word and the vocabulary cannot blow up;
 *  - at most TP_MAX_EXT_SLOTS distinct extensions are tracked in a fixed
 *    array (no allocation); a full table evicts its least frequent entry
 *    (lexicographic tie-break), so a dominant extension first seen late still
 *    displaces single-occurrence noise;
 *  - only the TP_MAX_EXT_TOKENS most frequent are emitted, ordered by
 *    (count desc, extension asc).
 * Emitted only when a file list is present, after the Stage 1c file tokens, so
 * name-only output stays byte-identical. */
#define TP_MAX_EXT_SLOTS 16
#define TP_MAX_EXT_TOKENS 8
#define TP_MAX_EXT_LEN 8

typedef struct {
    char ext[TP_MAX_EXT_LEN + 1];
    unsigned count;
} ext_slot_t;

static int ext_eligible(const char *ext) {
    size_t len = strlen(ext);
    if (len == 0 || len > TP_MAX_EXT_LEN) return 0;
    for (size_t i = 0; i < len; i++) {
        if (!isalnum((unsigned char)ext[i])) return 0;
    }
    return 1;
}

static void ext_count(ext_slot_t *slots, int *n_slots, const char *ext) {
    if (!ext_eligible(ext)) return;
    for (int i = 0; i < *n_slots; i++) {
        if (strcmp(slots[i].ext, ext) == 0) {
            slots[i].count++;
            return;
        }
    }
    if (*n_slots < TP_MAX_EXT_SLOTS) {
        snprintf(slots[*n_slots].ext, sizeof slots[*n_slots].ext, "%s", ext);
        slots[*n_slots].count = 1;
        (*n_slots)++;
        return;
    }
    int victim = 0;
    for (int i = 1; i < *n_slots; i++) {
        if (slots[i].count < slots[victim].count ||
            (slots[i].count == slots[victim].count &&
             strcmp(slots[i].ext, slots[victim].ext) < 0)) {
            victim = i;
        }
    }
    if (slots[victim].count > 1) return; /* never evict a repeated extension */
    snprintf(slots[victim].ext, sizeof slots[victim].ext, "%s", ext);
    slots[victim].count = 1;
}

static void put_ext_tokens(writer_t *w, const tp_file_t *files, int n_files) {
    ext_slot_t slots[TP_MAX_EXT_SLOTS];
    int n_slots = 0;
    for (int i = 0; i < n_files; i++) {
        if (files[i].path == NULL) continue;
        char ext[16];
        if (!file_ext(files[i].path, ext, sizeof ext)) continue;
        ext_count(slots, &n_slots, ext);
    }
    for (int k = 0; k < TP_MAX_EXT_TOKENS; k++) {
        int best = -1;
        for (int i = 0; i < n_slots; i++) {
            if (slots[i].count == 0) continue;
            if (best < 0 || slots[i].count > slots[best].count ||
                (slots[i].count == slots[best].count &&
                 strcmp(slots[i].ext, slots[best].ext) < 0)) {
                best = i;
            }
        }
        if (best < 0) break;
        w_token(w, "__ext_", slots[best].ext);
        slots[best].count = 0; /* emit each extension at most once */
    }
}

/* --- Stage 4 (adult): curated whole-token adult evidence ----------------- */

/* Emits at most one token per family, after the extension tokens:
 *  - `__adult_jav`  a curated studio prefix immediately followed by 2-5 digits
 *                   (`SUPA-620`, `SUPA 620`, `SUPA620`, `SKMJ-685ch`);
 *  - `__adult_site` a curated site/studio term as one whole token, or as two
 *                   adjacent tokens joined (`Met-Art` -> `met`+`art`);
 *  - `__adult_set`  one nudity/explicit term AND one AI-pack marker anywhere in
 *                   the name (`InniePussy1 v4 Inpainting-000005.safetensors`).
 * Matching is whole-token only (one strcmp per candidate, no substring search),
 * so `private`, `babes`, `art`, `model-3` and `x265-10bit` never fire, and the
 * name is scanned once with two fixed 33-byte token buffers: no allocation. */

#define TP_ADULT_TOKEN_CAP 33

typedef struct {
    char text[TP_ADULT_TOKEN_CAP];
    size_t len;
} adult_token_t;

static int adult_term_eq(const char *const *terms, size_t n, const adult_token_t *tok) {
    for (size_t i = 0; i < n; i++) {
        const char *term = terms[i];
        if (strlen(term) == tok->len && strncmp(term, tok->text, tok->len) == 0) return 1;
    }
    return 0;
}

/* Two adjacent tokens joined equal a curated term (`met`+`art` -> `metart`). */
static int adult_pair_eq(const char *const *terms, size_t n, const adult_token_t *a, const adult_token_t *b) {
    for (size_t i = 0; i < n; i++) {
        const char *term = terms[i];
        size_t tl = strlen(term);
        if (tl != a->len + b->len) continue;
        if (strncmp(term, a->text, a->len) == 0 && strncmp(term + a->len, b->text, b->len) == 0) return 1;
    }
    return 0;
}

/* A curated term, or two tokens joined across exactly one separator character:
 * `met-art` and `x art` join, `all - stars` does not (a code or a site name is
 * `PREFIX-123` / `Met-Art`, never `a - b`). */
static int adult_match(const char *const *terms, size_t n, const adult_token_t *cur, const adult_token_t *prev, size_t sep) {
    if (adult_term_eq(terms, n, cur)) return 1;
    return prev != NULL && sep == 1 && adult_pair_eq(terms, n, prev, cur);
}

/* The set family is the one place a curated term may sit *inside* a token: AI
 * packs compound the word with a version (`InniePussy1`, `Ass-CameltoeV1.2`), so
 * a whole-token rule would never fire on them. It is safe here only because the
 * family also requires an AI/checkpoint marker in the same name, and every entry
 * in that list is >= 4 chars and unambiguous (no `ass`, `sex`, `art`). */
static int adult_contains(const char *const *terms, size_t n, const adult_token_t *tok) {
    for (size_t i = 0; i < n; i++) {
        if (strstr(tok->text, terms[i]) != NULL) return 1;
    }
    return 0;
}

/* `SUPA620`: the prefix and the digits fused into one token. */
static int adult_jav_fused(const adult_token_t *tok) {
    for (size_t i = 0; i < TP_ADULT_JAV_PREFIXES_COUNT; i++) {
        const char *p = TP_ADULT_JAV_PREFIXES[i];
        size_t pl = strlen(p);
        if (tok->len <= pl || tok->len > pl + 5) continue;
        if (strncmp(tok->text, p, pl) != 0) continue;
        size_t digits = 0;
        while (pl + digits < tok->len && isdigit((unsigned char)tok->text[pl + digits])) digits++;
        if (digits >= 2 && pl + digits == tok->len) return 1;
    }
    return 0;
}

/* `SUPA-620`: the prefix token, one separator, then a token starting with 2-5
 * digits. The single-separator rule is what keeps `09-Jul-94`, `all - stars` and
 * `Ryoumin ... -sama - 03` out; the prefixes that still collide as English words
 * (`stars`, `jul`, `aldn`, ...) are excluded from the list instead. */
static int adult_jav_pair(const adult_token_t *prefix, const adult_token_t *next, size_t sep) {
    if (sep != 1) return 0;
    for (size_t i = 0; i < TP_ADULT_JAV_PREFIXES_COUNT; i++) {
        const char *p = TP_ADULT_JAV_PREFIXES[i];
        size_t pl = strlen(p);
        if (prefix->len != pl || strncmp(prefix->text, p, pl) != 0) continue;
        size_t digits = 0;
        while (digits < next->len && digits < 5 && isdigit((unsigned char)next->text[digits])) digits++;
        if (digits >= 2 && (digits == next->len || !isdigit((unsigned char)next->text[digits]))) return 1;
    }
    return 0;
}

typedef struct {
    int jav;
    int site;
    int set_adult;
    int set_marker;
} adult_flags_t;

/* One pass over `text`: every family is independent and stops at its first hit,
 * so a row pays for the families it has not matched yet only. */
static void adult_scan(const char *text, adult_flags_t *f) {
    adult_token_t prev, cur;
    int have_prev = 0;
    const char *p = text;
    while (*p != '\0') {
        size_t sep = 0;
        while (*p != '\0' && !isalnum((unsigned char)*p)) {
            p++;
            sep++;
        }
        if (*p == '\0') break;
        cur.len = 0;
        while (*p != '\0' && isalnum((unsigned char)*p)) {
            if (cur.len + 1 < TP_ADULT_TOKEN_CAP) {
                cur.text[cur.len++] = (char)tolower((unsigned char)*p);
            }
            p++;
        }
        cur.text[cur.len] = '\0';
        if (!f->jav) {
            f->jav = adult_jav_fused(&cur) || (have_prev && adult_jav_pair(&prev, &cur, sep));
        }
        const adult_token_t *before = have_prev ? &prev : NULL;
        if (!f->site) {
            f->site = adult_match(TP_ADULT_SITE_TERMS, TP_ADULT_SITE_TERMS_COUNT, &cur, before, sep);
        }
        if (!f->set_adult) {
            f->set_adult = adult_contains(TP_ADULT_SET_ADULT_TERMS, TP_ADULT_SET_ADULT_TERMS_COUNT, &cur);
        }
        if (!f->set_marker) {
            f->set_marker = adult_match(
                TP_ADULT_SET_MARKER_TERMS, TP_ADULT_SET_MARKER_TERMS_COUNT, &cur, before, sep
            );
        }
        prev = cur;
        have_prev = 1;
    }
}

/* Name evidence first, then each file path: an AI pack carries its marker in the
 * file name (`Ass-CameltoeV1.2.safetensors`) while the torrent name carries the
 * word, so the two families can be satisfied from different strings. */
static void put_adult_tokens(writer_t *w, const char *name, const tp_file_t *files, int n_files) {
    adult_flags_t f = { 0, 0, 0, 0 };
    if (name != NULL) adult_scan(name, &f);
    for (int i = 0; i < n_files; i++) {
        if (files[i].path != NULL) adult_scan(files[i].path, &f);
    }
    if (f.jav) w_token(w, "__adult_", "jav");
    if (f.site) w_token(w, "__adult_", "site");
    if (f.set_adult && f.set_marker) w_token(w, "__adult_", "set");
}

size_t tp_feature_text(const char *name, const tp_file_t *files, int n_files, const tp_result_t *r, char *buf, size_t cap) {
    writer_t w;
    w.buf = (buf != NULL && cap > 0) ? buf : NULL;
    w.cap = cap;
    w.len = 0;
    w.needed = 0;
    if (name != NULL) put_name_tokens(&w, name);
    if (r != NULL) {
        tp_name_info_t info;
        tp_name_scan((name != NULL) ? name : "", &info);
        put_feature_tokens(&w, r);
        put_source_res_tokens(&w, name, &info, r);
        if (files != NULL && n_files > 0) {
            tp_file_ev_t ev;
            collect_file_ev(files, n_files, &info, &ev);
            put_file_tokens(&w, &ev, n_files, r, info.resolution);
            put_ext_tokens(&w, files, n_files);
        }
        put_adult_tokens(&w, name, files, n_files);
    }
    if (w.buf != NULL) w.buf[w.len] = '\0';
    return w.needed;
}
